17: function initWorld(){world.platforms=[];world.hazards=[];world.pickups=[];world.drones=[];world.particles=[];world.buildings=[];world.rain=[];for(let i=0;i<36;i++)world.buildings.push({x:i*265,w:rnd(80,190),h:rnd(H*.12,H*.48),layer:i%3,seed:rnd(0,100)});let x=530;while(x<world.length-350){const type=Math.random();if(type<.22)world.platforms.push({x:x+60,y:world.ground-rnd(90,145),w:rnd(110,190),h:16});else if(type<.5)world.hazards.push({x:x+60,y:world.ground-18,w:rnd(38,68),h:18,type:'spike',alive:true});else if(type<.72)world.hazards.push({x:x+70,y:world.ground-rnd(38,78),w:25,h:25,type:'mine',alive:true});if(Math.random()<.78)for(let j=0;j<3;j++)world.pickups.push({x:x+80+j*31,y:world.ground-rnd(65,105),r:8,got:false,phase:rnd(0,7)});if(Math.random()<.64)world.drones.push({x:x+rnd(90,190),y:world.ground-rnd(95,180),baseY:0,phase:rnd(0,7),hp:2,alive:true});x+=rnd(280,420);}for(const d of world.drones)d.baseY=d.y;for(let i=0;i<110;i++)world.rain.push({x:rnd(0,W),y:rnd(0,H),len:rnd(5,18),speed:rnd(230,520),alpha:rnd(.08,.32)});}
