22: function ensureAudio(){if(!audio){try{audio=new(window.AudioContext||window.webkitAudioContext)();}catch(e){audio=null;}}if(audio&&audio.state==='suspended')audio.resume();}function sound(type){if(mute||!audio)return;const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);let f=type==='hit'?115:type==='pickup'?580:type==='jump'?210:type==='dash'?95:150;o.type=type==='pickup'?'sine':'sawtooth';o.frequency.setValueAtTime(f,now);o.frequency.exponentialRampToValueAtTime(f*(type==='pickup'?1.7:.55),now+.12);g.gain.setValueAtTime(.055,now);g.gain.exponentialRampToValueAtTime(.001,now+.16);o.start(now);o.stop(now+.17);}
23: function setKey(k,v){if(k==='jump'&&v)player.jumpBuffer=.14;if(k==='attack'&&v&&!keys.attack&&mode==='playing')attack();if(k==='dash'&&v&&!keys.dash&&mode==='playing')dash();keys[k]=v;}window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','shift'].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')setKey('left',true);if(k==='d'||k==='arrowright')setKey('right',true);if(k==='w'||k==='arrowup'||k===' ')setKey('jump',true);if(k==='j'||k==='x')setKey('attack',true);if(k==='shift'||k==='k')setKey('dash',true);if((k==='p'||k==='escape')&&!['menu','dead','won'].includes(mode))pauseGame();if(k==='enter'&&['menu','dead','won'].includes(mode))startGame();});window.addEventListener('keyup',e=>{let k=e.key.toLowerCase();if(k==='a'||k==='arrowleft')setKey('left',false);if(k==='d'||k==='arrowright')setKey('right',false);if(k==='w'||k==='arrowup'||k===' ')setKey('jump',false);if(k==='j'||k==='x')setKey('attack',false);if(k==='shift'||k==='k')setKey('dash',false);});document.querySelectorAll('.touch-btn').forEach(b=>{const k=b.dataset.key,down=e=>{e.preventDefault();ensureAudio();b.classList.add('down');setKey(k,true)},up=e=>{e.preventDefault();b.classList.remove('down');setKey(k,false)};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up);});
24: function attack(){if(player.attack>0)return;player.attack=.25;player.rage=Math.max(0,player.rage-9);sound('hit');const range=player.dash>0?110:86;for(const d of world.drones)if(d.alive&&Math.abs(d.x-player.x-player.facing*range*.55)<range&&Math.abs(d.y-(player.y+25))<95){d.hp--;d.x+=player.facing*22;if(d.hp<=0){d.alive=false;score+=180;player.rage=Math.min(100,player.rage+16);burst(d.x,d.y,'#b9ff39',16);}}for(const h of world.hazards)if(h.alive&&Math.abs(h.x-player.x-player.facing*range*.5)<range&&Math.abs(h.y-player.y)<110){h.alive=false;score+=60;burst(h.x,h.y,'#9bff43',10);}}
