function onFootInteract(){if(player.inCar){player.inCar=false;player.pos.copy(player.car.position);player.pos.x+=Math.cos(player.car.rotation.y)*2.1;player.pos.z+=Math.sin(player.car.rotation.y)*2.1;playerRoot.visible=true;toast('ON FOOT');return;}const q=missions[stage],dist=Math.hypot(player.pos.x-q.x,player.pos.z-q.z);if(dist<6.2){const current=q;questMarkers[stage].visible=false;const finish=()=>{stage++;player.bond=Math.min(100,player.bond+current.reward);ui.memory.textContent=`${Math.min(stage,4)} / 4`;if(stage>=missions.length){mode='win';ui.panel.innerHTML='<div class="eyebrow">ENDING // A CHOICE MADE TOGETHER</div><h1>THE CITY <span>BREATHES.</span></h1><p class="copy">The relay opens every lab door in Kestrel. By morning, the corporation’s secrets are on every screen. Nyx stays — not as a weapon, but as a voice beside yours. The city is still broken. This time, you face it together.</p><div class="storyline">“We can start with one street,” Nyx whispers. For the first time, it sounds like hope.</div><button class="primary" id="again">WALK THE CITY AGAIN ↻</button><div class="fine">THANK YOU FOR PLAYING CITY OF TEETH</div>';ui.overlay.classList.remove('hidden');document.querySelector('#again').onclick=()=>location.reload();return;}mode='playing';toast('MEMORY SYNCHRONIZED · BOND +'+current.reward);};dialogNext=finish;dialog(current.title,current.quote,stage===missions.length-1?'CHOOSE TOGETHER':'KEEP GOING');return;}
if(Math.hypot(player.pos.x-player.car.position.x,player.pos.z-player.car.position.z)<4.4){player.inCar=true;playerRoot.visible=false;toast('DRIVER SEAT // RADIO SIGNAL ACTIVE');return;}toast('NYX: GET CLOSER. I CAN’T HEAR THEM YET.');}
function attack(){if(mode!=='playing'||attackCooldown>0||player.bond<6)return;attackCooldown=.58;player.bond=Math.max(0,player.bond-5);player.attack=.42;let nearest=null,dist=13;for(const d of drones)if(d.alive){const n=player.pos.distanceTo(d.mesh.position);if(n<dist){dist=n;nearest=d;}}if(nearest){nearest.hp--;nearest.mesh.position.y+=1.2;if(nearest.hp<=0){nearest.alive=false;nearest.mesh.visible=false;player.bond=Math.min(100,player.bond+12);toast('HUNTER DISABLED · NYX FEEDS');}else toast('TENDRIL STRIKE');}else toast('NYX: LET ME REACH.');}
function keyAction(k,down){if(down&&mode==='menu'&&k==='enter'){document.querySelector('#start')?.click();return;}if(down&&k==='interact'){if(mode==='playing')onFootInteract();return;}if(down&&k==='attack'){attack();return;}if(down&&k==='pause'){pause();return;}keys[k]=down;}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='w'||k==='arrowup')keyAction('forward',true);else if(k==='s'||k==='arrowdown')keyAction('back',true);else if(k==='a'||k==='arrowleft')keyAction('left',true);else if(k==='d'||k==='arrowright')keyAction('right',true);else if(k==='e'||k==='enter')keyAction('interact',true);else if(k==='f'||k==='j')keyAction('attack',true);else if(k===' '||k==='shift')keyAction(k===' '? 'jump':'sprint',true);else if(k==='escape'||k==='p')keyAction('pause',true);});window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='w'||k==='arrowup')keyAction('forward',false);else if(k==='s'||k==='arrowdown')keyAction('back',false);else if(k==='a'||k==='arrowleft')keyAction('left',false);else if(k==='d'||k==='arrowright')keyAction('right',false);else if(k===' '||k==='shift')keyAction(k===' '? 'jump':'sprint',false);});
for(const b of document.querySelectorAll('.tbtn')){const k=b.dataset.key,down=e=>{e.preventDefault();b.classList.add('down');keyAction(k,true);},up=e=>{e.preventDefault();b.classList.remove('down');keyAction(k,false);};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up);}
canvas.addEventListener('pointerdown',e=>{mouseDown=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointerup',()=>mouseDown=false);canvas.addEventListener('pointermove',e=>{if(!mouseDown||mode!=='playing')return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;cameraYaw-=dx*.004;cameraPitch=Math.max(-.1,Math.min(.6,cameraPitch+dy*.0025));});
function isBlocked(x,z,radius=0){for(const b of towers)if(Math.abs(x-b.x)<b.w/2+radius&&Math.abs(z-b.z)<b.d/2+radius)return true;return false;}
function updateHud(){ui.sync.textContent=`${Math.round(player.bond)}%`;ui.health.style.width=`${player.hp}%`;ui.bond.style.width=`${player.bond}%`;ui.missionTitle.textContent=`MISSION // ${missions[Math.min(stage,3)].name}`;ui.missionText.textContent=missions[Math.min(stage,3)].text;const x=player.inCar?player.car.position.x:player.pos.x,z=player.inCar?player.car.position.z:player.pos.z;ui.district.textContent=missions[Math.min(stage,3)].district;ui.distance.textContent=`N ${String(Math.round(-z+4)).padStart(3,'0')} / E ${String(Math.round(x+8)).padStart(3,'0')}`;ui.memory.textContent=`${stage} / 4`;}
function interactPrompt(){if(mode!=='playing'){ui.prompt.classList.remove('show');return;}const q=missions[stage],d=Math.hypot(player.pos.x-q.x,player.pos.z-q.z);if(player.inCar){ui.prompt.textContent='E  EXIT VEHICLE';ui.prompt.classList.add('show');return;}if(d<7){ui.prompt.textContent=`E  ${q.title}`;ui.prompt.classList.add('show');return;}const carDist=Math.hypot(player.pos.x-player.car.position.x,player.pos.z-player.car.position.z);if(carDist<5){ui.prompt.textContent='E  ENTER VEHICLE';ui.prompt.classList.add('show');return;}ui.prompt.classList.remove('show');}
function move(dt){const p=player;if(p.inCar){const car=p.car,steer=(keys.right?1:0)-(keys.left?1:0),throttle=(keys.forward?1:0)-(keys.back?1:0);if(throttle){car.userData.speed=(car.userData.speed||0)+throttle*dt*14;}else car.userData.speed=(car.userData.speed||0)*Math.pow(.35,dt);car.userData.speed=Math.max(-9,Math.min(keys.sprint?31:23,car.userData.speed));if(Math.abs(car.userData.speed)>.5)car.rotation.y+=steer*dt*Math.sign(car.userData.speed)*1.45;const nx=car.position.x+Math.sin(car.rotation.y)*-car.userData.speed*dt,nz=car.position.z+Math.cos(car.rotation.y)*-car.userData.speed*dt;if(!isBlocked(nx,nz,1.8)){car.position.x=THREE.MathUtils.clamp(nx,-WORLD+3,WORLD-3);car.position.z=THREE.MathUtils.clamp(nz,-WORLD+3,WORLD-3);}p.pos.copy(car.position);playerRoot.position.copy(car.position);playerRoot.rotation.y=car.rotation.y;return;}
const forward=(keys.forward?1:0)-(keys.back?1:0),side=(keys.right?1:0)-(keys.left?1:0),speed=keys.sprint?13:8;const moveX=(Math.sin(cameraYaw)*forward+Math.cos(cameraYaw)*side)*speed,moveZ=(-Math.cos(cameraYaw)*forward+Math.sin(cameraYaw)*side)*speed;const nx=p.pos.x+moveX*dt,nz=p.pos.z+moveZ*dt;if(!isBlocked(nx,p.pos.z,.48))p.pos.x=THREE.MathUtils.clamp(nx,-WORLD+2,WORLD-2);if(!isBlocked(p.pos.x,nz,.48))p.pos.z=THREE.MathUtils.clamp(nz,-WORLD+2,WORLD-2);if(Math.abs(moveX)+Math.abs(moveZ)>.3){playerRoot.rotation.y=Math.atan2(moveX,-moveZ);body.position.y=Math.abs(Math.sin(time*10))*.07;}else body.position.y=0;playerRoot.position.set(p.pos.x,0,p.pos.z);if(keys.jump&&p.grounded){p.grounded=false;p.vel.y=6.2;}if(!p.grounded){p.vel.y-=18*dt;playerRoot.position.y+=p.vel.y*dt;if(playerRoot.position.y<=0){playerRoot.position.y=0;p.vel.y=0;p.grounded=true;}}}

